function hitTrackHero(frame,bob,lean,recoil) {
    const i=frame.row*5+frame.column,box=HERO_MOTION_FRAMES[frame.id].frames[i];
    const key='hero/'+frame.id+'/'+i,h=heroDrawHeight(frame.row);
    // CSS rotates about (foot pivot X, 90% height). Use the same visible pose,
    // including its recoil, bob, mirrored direction and rotation.
    if(!hitHeroArt||hitHeroArt.key!==key||hitHeroArt.lean!==lean||hitHeroArt.flip!==frame.flip) {
        hitHeroArt={key,id:frame.id,lean,flip:frame.flip,
            pose:hitPose(key,box[2]*h/box[3],h,box[4]/100,.9,lean*Math.PI/180,frame.flip)};
    }
    hitHeroArt.x=recoil.x;hitHeroArt.y=30+bob+recoil.y-h*.1;
}
function hitCurrentHero() {
    if(!hitHeroArt||hitHeroArt.id!==gameData.character)
        hitTrackHero({id:gameData.character,row:0,column:0,flip:false},0,0,{x:0,y:0});
    return hitHeroArt;
}
